/*
 * A367349  List of numbers in the range 1 to 99 missing from A366487.
 * https://oeis.org/A367349
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full
 * Formula:   a(n) = n-th number k in 1..99 that is never a difference
 *            a(j+1)-a(j) of A121805 (A121805 generated by search until it
 *            terminates)
 * Range:     u8 n <= 16, u16 n <= 16, u32 n <= 16, u64 n <= 16, u128 n <= 16,
 *            big any n
 * Validated: partial, pass, 16 terms through n = 16 (2026-11-10)
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>

static uint64_t A367349_msd(uint64_t x)
{
    while (x >= 10) x /= 10;
    return x;
}

seq_t a(idx_t n)
{
    static bool ready = false;
    static int list[100];
    static int cnt = 0;
    if (!ready) {
        bool seen[200];
        for (int i = 0; i < 200; i++) seen[i] = false;
        uint64_t prev = 1;
        for (uint64_t it = 0; it < 2000000; it++) {
            uint64_t base = prev + (prev % 10) * 10;
            uint64_t val = 0;
            for (uint64_t d = 0; d <= 9; d++) {
                uint64_t cand = base + d;
                if (A367349_msd(cand) == d) { val = cand; break; }
            }
            if (val == 0) break;
            uint64_t diff = val - prev;
            if (diff < 200) seen[diff] = true;
            prev = val;
        }
        for (int k = 1; k <= 99; k++)
            if (!seen[k]) list[cnt++] = k;
        ready = true;
    }
    if (n < 1 || n > (idx_t)cnt) return (seq_t)0;
    return (seq_t)list[n - 1];
}
